from __future__ import annotations
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
LAYOUTS = json.loads((ROOT / "scratch/t05/layouts.json").read_text(encoding="utf-8"))["layouts"]
SCHEMA = json.loads((ROOT / "scratch/t05/schema_inventory.json").read_text(encoding="utf-8"))["entities"]

CITY = {
    1: {
        "code": "<Clat+Clon 合并>", "components": ["Clat", "Clon"],
        "evidence": "56,293 行均为有限 f32 对：row+1 纬度 -54.8127..78.2243，row+5 经度 -179.9813..179.55；与 schema 两个 real 字段吻合，且 city_reference 明确两者。",
        "validation": {"kind": "f32_pair", "profile": "profile_{archive}2_city.json", "offsets": [1, 5],
                       "ranges": [[-90, 90], [-180, 180]]},
    },
    3: {
        "code": "Cnti", "schema_type": "database_record_unique_id",
        "evidence": "u32 distinct=230，min/max=0..249，0xFFFFFFFF 比率=0；nation 表 251 行且 ref_lt_251=1.0；schema 类型 database_record_unique_id。city_reference 与任务基准均指定 Cnti@10。",
        "validation": {"kind": "reference", "profile": "profile_{archive}2_city_ref251_nation.json", "offset": 10,
                       "target_count": 251, "allow_ff": False},
    },
    4: {
        "code": "Cwea", "schema_type": "database_record_unique_id",
        "evidence": "u32 distinct=321，min/max=0..333，0xFFFFFFFF 比率=0；weather profile 表 334 行且 ref_lt_334=1.0；符合 4B database_record_unique_id。",
        "validation": {"kind": "reference", "profile": "profile_{archive}2_city_ref334_weather.json", "offset": 14,
                       "target_count": 334, "allow_ff": False},
    },
    6: {
        "code": "Clgi", "schema_type": "database_record_unique_id",
        "evidence": "u32 distinct=61；0xFFFFFFFF 哨兵比率=0.8173；其余 18.27% 全部 < language 表 126 行(ref_lt_126=0.1827)，可作为可空引用。",
        "validation": {"kind": "reference", "profile": "profile_{archive}2_city_ref126_language.json", "offset": 21,
                       "target_count": 126, "allow_ff": True},
    },
    7: {
        "code": "Clri", "schema_type": "database_record_unique_id",
        "evidence": "u32 distinct=2330；0xFFFFFFFF 哨兵比率=0.0835；其余 91.65% 全部 < local-region 表 2488 行(ref_lt_2488=0.9165)，可作为可空引用。",
        "validation": {"kind": "reference", "profile": "profile_{archive}2_city_ref2488_localregion.json", "offset": 25,
                       "target_count": 2488, "allow_ff": True},
    },
}
INJURY = {
    0: ("icla", "enum", "u8", 1, 13, 11, "值域 1–13，11 种"),
    3: ("Imnd", "integer", "u16", 1, 180, 22, "值域 1–180，22 种"),
    5: ("Imio", "integer (exe-only; schema_inventory 无该码)", "u16", 3, 290, 29, "值域 3–290，29 种"),
    8: ("Irec", "boolean", "u8", 0, 1, 2, "严格 {0,1}"),
    17: ("Imip", "integer", "u8", 0, 90, 10, "值域 0–90，10 种"),
    21: ("Icms", "enum", "u8", 0, 3, 4, "严格 {0,1,2,3} 四季"),
    23: ("inSr", "enum", "u8", 1, 5, 5, "值域 1–5，五级"),
    25: ("Icdp", "integer", "u8", 50, 255, 2, "{50,255}；0xFF 为不适用哨兵，ff_ratio=0.9826"),
    26: ("Icdo", "integer (exe-only; schema_inventory 无该码)", "u8", 1, 51, 15, "值域 1–51"),
}

def schema_type(entity: str, code: str):
    key = {"inju": "injury", "regi": "region", "stad": "stadium", "city": "city"}.get(entity)
    if not key or key not in SCHEMA:
        return None
    return next((f["type"] for f in SCHEMA[key]["fields"] if f["code"] == code), None)

def safe_entity(name, tid):
    return name if name not in (None, "?") else f"unknown_type{tid}"

def profile_path(archive, tid, entity):
    safe = safe_entity(entity, tid)
    options = [OUT / f"profile_{archive}{tid}_{safe}.json"]
    if (archive, tid) == ("client", 2): options.append(OUT / "profile_client2_city.json")
    if (archive, tid) == ("server", 2): options.append(OUT / "profile_server2_city.json")
    if (archive, tid) == ("server", 6): options.append(OUT / "profile_server6_inju.json")
    if (archive, tid) == ("client", 21): options.append(OUT / "profile_client21_stad.json")
    if (archive, tid) == ("client", 47): options.append(OUT / "profile_client47_lcrg.json")
    return next((p for p in options if p.exists()), None)

def summarize_column(p, off, width):
    if p is None:
        return "no row-level profile: auto parser failed its closure check (14 + 7115*44 + 8 != payload length 12); row grammar unavailable"
    d = json.loads(p.read_text(encoding="utf-8")); cols = d["columns"]
    if off >= len(cols):
        return f"profile {p.name} has width={len(cols)}, no column at offset {off}"
    c = cols[off]
    parts = [f"profile={p.name}, rows={d['rows']}, byte@{off} distinct={c['distinct_u8']} range={c['min_u8']}..{c['max_u8']} ff_ratio={c['ff_ratio_u8']:.4f}"]
    if width >= 2 and "u16" in c:
        u = c["u16"]; parts.append(f"u16 distinct={u['distinct']} range={u['min']}..{u['max']} ff_ratio={u['ff_ratio']:.4f}")
    if width >= 4 and "u32" in c:
        u = c["u32"]; parts.append(f"u32 distinct={u['distinct']} range={u['min']}..{u['max']} ff_ratio={u['ff_ratio']:.4f}")
        if "ref_lt_N" in u: parts.append(f"ref_lt_N={u['ref_lt_N']}")
    if "f32" in c:
        f = c["f32"]; parts.append(f"f32 finite_ratio={f['finite_ratio']:.4f} range={f['min']}..{f['max']}")
    return "; ".join(parts)

def build():
    assignments = []
    for ent in LAYOUTS:
        tid, entity = ent["type_id"], ent["entity"]
        for archive, layout in ent["archives"].items():
            pp = profile_path(archive, tid, entity)
            slots = []
            for f in layout["fields"]:
                off, width, idx = f["row_off"], f["width"], f["idx"]
                item = {"idx": idx, "row_off": off, "width": width, "code": "unresolved",
                        "confidence": "unresolved", "evidence": summarize_column(pp, off, width)}
                reason = "type profile alone does not uniquely distinguish a schema field; leave unnamed rather than use schema order"
                if tid == 2 and idx in CITY:
                    spec = CITY[idx]
                    item.update({"code": spec["code"], "confidence": "high", "evidence": spec["evidence"],
                                 "validation": dict(spec["validation"], profile=spec["validation"]["profile"].format(archive=archive))})
                    if "components" in spec:
                        item["component_codes"] = spec["components"]
                        item["schema_types"] = {c: schema_type("city", c) for c in spec["components"]}
                    else:
                        item["schema_type"] = spec["schema_type"]
                elif tid == 2 and idx == 0:
                    item["evidence"] = "profile: constant 0 in all 56,293 rows; no matching scalar field can be identified from a constant byte."
                    item["unresolved_reason"] = "constant/padding-like byte; no discriminating value evidence"
                elif tid == 2 and idx == 2:
                    item["evidence"] += "; candidate city codes Catt(integer) / Cinh(enum) both accept a low-cardinality byte, so type alone is ambiguous"
                    item["candidate_codes"] = ["Catt", "Cinh"]
                    item["unresolved_reason"] = "no independent field anchor or legal-enum cardinality to separate Catt from Cinh"
                elif tid == 2 and idx == 5:
                    item["evidence"] += "; 3B reader chunk may contain subfields, but its internal field boundaries are not established"
                    item["candidate_codes"] = ["Calt", "Cinh"]
                    item["unresolved_reason"] = "no proven split of the 3B read into Calt/Cinh; do not split a fixed reader slot speculatively"
                elif tid == 2 and idx == 8:
                    item["unresolved_reason"] = "byte values {0,2} do not uniquely match a schema field; no independent semantic anchor"
                elif tid == 19 and archive == "server" and idx == 8:
                    item.update({"code": "boundary_marker", "confidence": "high",
                                 "schema_type": "structural boundary marker (not a schema field)",
