                  "| idx | row_off | width | 分配 | 置信度 | 数据证据 / unresolved 原因 |", "|---:|---:|---:|---|---|---|"]
        for s in a["slots"]:
            code = s["code"]
            if s.get("component_codes"): code += " (`" + "+".join(s["component_codes"]) + "`)"
            evidence = s.get("evidence", "")
            if s.get("unresolved_reason"): evidence += "；原因：" + s["unresolved_reason"]
            lines.append(f"| {s['idx']} | {s['row_off']} | {s['width']} | `{code}` | {s['confidence']} | {evidence} |")
